input.dsl:
workspace "Order Service" "A C4 model of the order processing system" {
    model {
        customer = person "Customer" "A customer who places orders"
        orders = softwareSystem "Order Service" "Manages customer orders" {
            web = container "Web App" "The customer-facing web application" "React" "Web"
            api = container "API" "The REST API for orders" "Spring Boot"
            db = container "Order Database" "Stores order data" "PostgreSQL" "Database"
            queue = container "Event Queue" "Buffers order events" "RabbitMQ" "Queue"
            worker = container "Order Worker" "Processes order events" "Spring Boot"
        }
        payments = softwareSystem "Payment Provider" "External payment processing" "External"

        customer -> web "Places orders through" "HTTPS"
        web -> api "Submits order requests to" "HTTPS/JSON"
        api -> db "Persists orders to" "SQL"
        api -> queue "Publishes order events to" "AMQP" "Async"
        worker -> queue "Consumes order events from" "AMQP" "Async"
        worker -> db "Updates order status in" "SQL"
        api -> payments "Charges customers via" "HTTPS/JSON"
    }
    views {
        systemLandscape "Landscape" "All systems in the landscape" {
            include *
            autoLayout
            title "System Landscape"
        }
        systemContext orders "SystemContext" "The Order Service and its users" {
            include *
            autoLayout
            title "System Context for Order Service"
        }
        container orders "Containers" "The containers of the Order Service" {
            include *
            autoLayout
            title "Containers for Order Service"
        }
        dynamic orders "OrderFlow" "The order placement flow" {
            customer -> web "Places orders through" "HTTPS"
            web -> api "Submits order requests to" "HTTPS/JSON"
            api -> db "Persists orders to" "SQL"
            api -> queue "Publishes order events to" "AMQP"
            autoLayout
            title "Order Placement Flow"
        }
        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            element "Queue" {
                shape Pipe
            }
            relationship "Relationship" {
                routing Orthogonal
            }
            relationship "Async" {
                style dashed
            }
        }
    }
}

